package com.spark.falcon.inventory.entity;
import jakarta.persistence.*;import lombok.*;import java.math.*;
@Entity @Table(name="branch_transfer_items",uniqueConstraints=@UniqueConstraint(name="uk_transfer_item_variant_batch",columnNames={"transfer_id","product_variant_id","source_batch_id"})) @Getter @NoArgsConstructor
public class BranchTransferItem {@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="transfer_id",nullable=false)private BranchTransfer transfer;@Column(name="product_variant_id",nullable=false)private Long productVariantId;@Column(name="source_batch_id")private Long sourceBatchId;@Column(name="destination_batch_id")private Long destinationBatchId;@Column(name="entered_quantity",nullable=false,precision=19,scale=8)private BigDecimal enteredQuantity;@Column(name="entered_unit_id",nullable=false)private Long enteredUnitId;@Column(name="conversion_factor",nullable=false,precision=19,scale=8)private BigDecimal conversionFactor;@Column(name="base_quantity",nullable=false,precision=19,scale=8)private BigDecimal baseQuantity;@Column(name="transfer_unit_cost_snapshot",nullable=false,precision=19,scale=4)private BigDecimal transferUnitCostSnapshot;@Column(name="dispatched_quantity",nullable=false,precision=19,scale=8)private BigDecimal dispatchedQuantity=BigDecimal.ZERO.setScale(8);@Column(name="received_quantity",nullable=false,precision=19,scale=8)private BigDecimal receivedQuantity=BigDecimal.ZERO.setScale(8);@Column(name="damaged_quantity",nullable=false,precision=19,scale=8)private BigDecimal damagedQuantity=BigDecimal.ZERO.setScale(8);@Column(name="missing_quantity",nullable=false,precision=19,scale=8)private BigDecimal missingQuantity=BigDecimal.ZERO.setScale(8);@Column(name="rejected_quantity",nullable=false,precision=19,scale=8)private BigDecimal rejectedQuantity=BigDecimal.ZERO.setScale(8);@Column(name="discrepancy_reason",length=500)private String discrepancyReason;@Column(name="discrepancy_resolved",nullable=false)private boolean discrepancyResolved;@Enumerated(EnumType.STRING)@Column(name="discrepancy_resolution_type",length=20)private TransferDiscrepancyResolutionType discrepancyResolutionType;@Column(name="discrepancy_resolution_reference",length=160)private String discrepancyResolutionReference;@Column(name="discrepancy_resolved_by")private Long discrepancyResolvedBy;@Column(name="discrepancy_resolved_at")private java.time.Instant discrepancyResolvedAt;@Column(name="transfer_out_movement_id",unique=true)private Long transferOutMovementId;@Column(name="transfer_in_movement_id",unique=true)private Long transferInMovementId;
 public static BranchTransferItem create(Long v,Long batch,BigDecimal entered,Long unit,BigDecimal factor,BigDecimal base,BigDecimal cost){if(base==null||base.signum()<=0||factor==null||factor.signum()<=0)throw new IllegalArgumentException("Positive Transfer quantity and conversion are required");BranchTransferItem i=new BranchTransferItem();i.productVariantId=v;i.sourceBatchId=batch;i.enteredQuantity=entered;i.enteredUnitId=unit;i.conversionFactor=factor;i.baseQuantity=base;i.transferUnitCostSnapshot=cost;return i;}void attach(BranchTransfer t){transfer=t;}public void refreshTransferUnitCostSnapshot(BigDecimal cost){if(cost==null||cost.signum()<0)throw new IllegalArgumentException("Transfer cost snapshot must not be negative");transferUnitCostSnapshot=cost;}public void dispatched(Long movement){dispatchedQuantity=baseQuantity;transferOutMovementId=movement;}public BigDecimal remaining(){return dispatchedQuantity.subtract(receivedQuantity).subtract(damagedQuantity).subtract(missingQuantity).subtract(rejectedQuantity);}public void receive(BigDecimal accepted,BigDecimal damaged,BigDecimal missing,BigDecimal rejected,String reason,Long movement,Long destinationBatch){BigDecimal total=nz(accepted).add(nz(damaged)).add(nz(missing)).add(nz(rejected));if(total.signum()<=0||total.compareTo(remaining())>0)throw new IllegalArgumentException("Receipt disposition exceeds remaining dispatched quantity");if(nz(damaged).add(nz(missing)).add(nz(rejected)).signum()>0&&(reason==null||reason.isBlank()))throw new IllegalArgumentException("Discrepancy reason is required");receivedQuantity=receivedQuantity.add(nz(accepted));damagedQuantity=damagedQuantity.add(nz(damaged));missingQuantity=missingQuantity.add(nz(missing));rejectedQuantity=rejectedQuantity.add(nz(rejected));discrepancyReason=reason;if(accepted!=null&&accepted.signum()>0){transferInMovementId=movement;destinationBatchId=destinationBatch;}}public void resolveDiscrepancy(TransferDiscrepancyResolutionType type,String reference,Long actor,java.time.Instant now){if(discrepancyResolved)throw new IllegalStateException("Transfer discrepancy is already resolved");if(damagedQuantity.add(missingQuantity).add(rejectedQuantity).signum()==0)throw new IllegalStateException("No discrepancy to resolve");if(type==null)throw new IllegalArgumentException("Discrepancy resolution type is required");if(reference==null||reference.isBlank())throw new IllegalArgumentException("Linked discrepancy resolution reference is required");discrepancyResolved=true;discrepancyResolutionType=type;discrepancyResolutionReference=reference.trim();discrepancyResolvedBy=actor;discrepancyResolvedAt=now;}public boolean fullyResolved(){boolean has=damagedQuantity.add(missingQuantity).add(rejectedQuantity).signum()>0;return remaining().signum()==0&&(!has||discrepancyResolved);}private BigDecimal nz(BigDecimal v){if(v==null)return BigDecimal.ZERO.setScale(8);if(v.signum()<0)throw new IllegalArgumentException("Receipt quantities must not be negative");return v;}
}
